pc.script.createLoadingScreen(function (app) {
    // SETTINGS
    var USE_FAKE_PROGRESS = true; // Set to false to use real loading progress
    var SHOW_SPINNER = false; // Set to true to show the spinning wheel

    var showSplash = function () {
        // splash wrapper
        var wrapper = document.createElement('div');
        wrapper.id = 'application-splash-wrapper';
        document.body.appendChild(wrapper);

        // splash
        var splash = document.createElement('div');
        splash.id = 'application-splash';

        wrapper.appendChild(splash);
        splash.style.display = 'none';

        var logo = document.createElement('img');
        // logo.src = 'https://playcanvas.com/static-assets/images/play_text_252_white.png';
        // logo.src = 'https://www.mageclash.io/assets/ui/icon_glyph_shop_1_256.png';        
        logo.src = 'data:image/png;base64,'

        
        splash.appendChild(logo);
        logo.onload = function () {
            splash.style.display = 'block';
        };

        var container = document.createElement('div');
        container.id = 'progress-bar-container';
        splash.appendChild(container);

        var innerContainer = document.createElement('div');
        innerContainer.id = 'progress-bar-inner';
        container.appendChild(innerContainer);

        var bar = document.createElement('div');
        bar.id = 'progress-bar';
        innerContainer.appendChild(bar);

        var progressText = document.createElement('div');
        progressText.id = 'progress-text';
        progressText.textContent = '0%';
        innerContainer.appendChild(progressText);

        // Spinning wheel (optional)
        if (SHOW_SPINNER) {
            var spinner = document.createElement('div');
            spinner.id = 'loading-spinner';
            splash.appendChild(spinner);
        }

        // Evolution animation
        var evoContainer = document.createElement('div');
        evoContainer.id = 'evolution-animation';
        splash.appendChild(evoContainer);

        // Creature wrapper for positioning sparkles
        var creatureWrapper = document.createElement('div');
        creatureWrapper.id = 'creature-wrapper';
        evoContainer.appendChild(creatureWrapper);

        var creature = document.createElement('span');
        creature.id = 'creature';
        creatureWrapper.appendChild(creature);

        // Sparkle container (inside creature wrapper)
        var sparkleContainer = document.createElement('div');
        sparkleContainer.id = 'sparkle-container';
        creatureWrapper.appendChild(sparkleContainer);

        var enemy = document.createElement('span');
        enemy.id = 'enemy';
        evoContainer.appendChild(enemy);

        // XP bar (below evo container)
        var xpBarContainer = document.createElement('div');
        xpBarContainer.id = 'xp-bar-container';
        splash.appendChild(xpBarContainer);

        var xpBar = document.createElement('div');
        xpBar.id = 'xp-bar';
        xpBarContainer.appendChild(xpBar);

        var levelDisplay = document.createElement('span');
        levelDisplay.id = 'level-display';
        levelDisplay.textContent = 'LV.1';
        xpBarContainer.appendChild(levelDisplay);

        var levelUp = document.createElement('div');
        levelUp.id = 'level-up';
        levelUp.textContent = 'LVL UP!';
        splash.appendChild(levelUp);


        // Pre-create sparkle elements for reuse
        var sparkles = [];
        for (var i = 0; i < 8; i++) {
            var sparkle = document.createElement('span');
            sparkle.className = 'sparkle';
            sparkle.textContent = '✨';
            sparkleContainer.appendChild(sparkle);
            sparkles.push(sparkle);
        }

        // Evolution stages: gecko -> snake -> crocodile -> dragon
        var evolutionStages = ['🦎', '🐍', '🐊', '🐉'];
        // Enemies/food to attack
        var enemies = ['🍖', '🦴', '💀', '👻', '🐀', '🐛', '🦟', '🪲', '🐜'];
        var currentStage = 0;
        var currentLevel = 1;
        var killsThisLevel = 0;
        var totalKills = 0;

        // Kills needed for each level (1, 2, 3, 4, then repeats)
        var getKillsNeeded = function() {
            return currentStage + 1;
        };

        creature.textContent = evolutionStages[currentStage];
        enemy.textContent = enemies[Math.floor(Math.random() * enemies.length)];

        // Update XP bar
        var updateXpBar = function() {
            var progress = killsThisLevel / getKillsNeeded() * 100;
            xpBar.style.width = progress + '%';
        };

        // Trigger sparkles
        var triggerSparkles = function() {
            sparkles.forEach(function(sparkle, index) {
                var angle = (index / sparkles.length) * 360;
                var delay = index * 30;
                setTimeout(function() {
                    sparkle.style.setProperty('--angle', angle + 'deg');
                    sparkle.classList.add('active');
                    setTimeout(function() {
                        sparkle.classList.remove('active');
                    }, 500);
                }, delay);
            });
        };

        updateXpBar();


        evoInterval = setInterval(function() {
            // Creature attacks with rotation
            creature.classList.add('attacking');
            
            setTimeout(function() {
                // Enemy gets eaten
                enemy.classList.add('eaten');
            }, 150);
            
            setTimeout(function() {
                creature.classList.remove('attacking');
                enemy.classList.remove('eaten');
                
                // Increment kill counts
                killsThisLevel++;
                totalKills++;
                
                // Update XP bar
                updateXpBar();
                
                // Check if should evolve
                if (killsThisLevel >= getKillsNeeded()) {
                    killsThisLevel = 0;
                    currentStage = (currentStage + 1) % evolutionStages.length;
                    currentLevel++;
                    levelDisplay.textContent = 'LV.' + currentLevel;
                    creature.classList.add('evolving');
                    levelUp.classList.add('show');
                    triggerSparkles();
                    // Reset XP bar visually
                    xpBar.style.width = '0%';
                    
                    setTimeout(function() {
                        creature.textContent = evolutionStages[currentStage];
                        creature.classList.remove('evolving');
                        levelUp.classList.remove('show');
                    }, 400);
                }
                
                // New enemy appears
                enemy.textContent = enemies[Math.floor(Math.random() * enemies.length)];
            }, 400);
        }, 1000);

        // Store interval to clear on hide

        app.once('preload:start', function () {           
            var logo = document.createElement('img');
            // logo.src = app.assets.find('loadingScreenTest.png', 'texture').getFileUrl(); 
            // logo.src =
            splash.insertBefore(logo, container);
        });
    };
         
    var splashBackgroundURL = 'data:image/png;base64,'

    var evoInterval = null; // Store globally to clear on hide

    var hideSplash = function () {
        if (evoInterval) {
            clearInterval(evoInterval);
        }
        var splash = document.getElementById('application-splash-wrapper');
        splash.parentElement.removeChild(splash);
    };

    var fakeProgress = 0;
    var fakeProgressInterval = null;

    var startFakeProgress = function () {
        fakeProgressInterval = setInterval(function () {
            // Slow down as we approach 90% to wait for real loading
            var increment = (0.9 - fakeProgress) * 0.02;
            fakeProgress = Math.min(0.9, fakeProgress + increment);
            updateProgressBar(fakeProgress);
        }, 50);
    };

    var completeFakeProgress = function () {
        if (fakeProgressInterval) {
            clearInterval(fakeProgressInterval);
            fakeProgressInterval = null;
        }
        // Quickly fill to 100%
        var completeInterval = setInterval(function () {
            fakeProgress += 0.05;
            if (fakeProgress >= 1) {
                fakeProgress = 1;
                clearInterval(completeInterval);
            }
            updateProgressBar(fakeProgress);
        }, 20);
    };

    var updateProgressBar = function (value) {
        var bar = document.getElementById('progress-bar');
        var progressText = document.getElementById('progress-text');
        if (bar) {
            value = Math.min(1, Math.max(0, value));
            bar.style.width = value * 100 + '%';
            if (progressText) {
                progressText.textContent = Math.round(value * 100) + '%';
            }
        }
    };

    var setProgress = function (value) {
        var bar = document.getElementById('progress-bar');
        var progressText = document.getElementById('progress-text');
        if(bar) {
            value = Math.min(1, Math.max(0, value));
            bar.style.width = value * 100 + '%';
            if(progressText) {
                progressText.textContent = Math.round(value * 100) + '%';
            }
        }
    };

    var createCss = function () {
        var css = [
            'body {',
            '}',
            '',
            '#application-splash-wrapper {',
            '    position: absolute;',
            '    top: 0;',
            '    left: 0;',
            '    height: 100%;',
            '    width: 100%;',
            '    background-image: url(' + splashBackgroundURL + ');',
            '    background-size: contain;',
            '    background-position: center center;',
            '    background-repeat: no-repeat;',
            '    background-color: #283538;',
            '}',
            '',
            '#application-splash {',
            '    position: absolute;',
            '    top: 50%;',
            '    left: 50%;',
            '    transform: translate(-50%, -50%);',
            '    width: 264px;',
            '    max-height: 90vh;',
            '    overflow: visible;',
            '}',
            '',
            '#application-splash img {',
            '    width: 100%;',
            '}',
            '',
            '#progress-bar-container {',
            '    position: relative;',
            '    margin: 20px auto 0 auto;',
            '    height: 12px;',
            '    width: 100%;',
            '    background: linear-gradient(90deg, #ff0000, #ff8000, #ffff00, #00ff00, #00ffff, #0080ff, #8000ff);',
            '    border-radius: 8px;',
            '    padding: 2px;',
            '    box-shadow: 0 0 8px rgba(255,100,0,0.5);',
            '    animation: border-glow 2s ease-in-out infinite;',
            '}',
            '',
            '#progress-bar-inner {',
            '    position: relative;',
            '    height: 100%;',
            '    width: 100%;',
            '    background-color: #1d292c;',
            '    border-radius: 6px;',
            '    overflow: visible;',
            '    box-shadow: inset 0 2px 4px rgba(0,0,0,0.5);',
            '}',
            '',
            '#progress-bar {',
            '    width: 0%;',
            '    height: 100%;',
            '    background: linear-gradient(90deg, #ff0000, #ff8000, #ffff00, #00ff00, #00ffff, #0080ff, #8000ff, #ff0000);',
            '    background-size: 200% 100%;',
            '    animation: rainbow-shift 2s linear infinite, pulse-glow 1.5s ease-in-out infinite;',
            '    border-radius: 6px;',
            '    box-shadow: 0 0 6px rgba(255,255,255,0.2), 0 0 12px rgba(255,150,0,0.15);',
            '    position: relative;',
            '}',
            '',
            '#progress-bar::before {',
            '    content: \"\";',
            '    position: absolute;',
            '    top: 0;',
            '    left: 0;',
            '    right: 0;',
            '    bottom: 0;',
            '    background: repeating-linear-gradient(',
            '        45deg,',
            '        rgba(255,255,255,0.08),',
            '        rgba(255,255,255,0.08) 10px,',
            '        transparent 10px,',
            '        transparent 20px',
            '    );',
            '    background-size: 200% 200%;',
            '    animation: stripe-move 0.8s linear infinite;',
            '    border-radius: 6px;',
            '}',
            '',
            '#progress-bar::after {',
            '    content: \"\";',
            '    position: absolute;',
            '    top: 0;',
            '    left: 0;',
            '    right: 0;',
            '    height: 50%;',
            '    background: linear-gradient(180deg, rgba(255,255,255,0.12) 0%, rgba(255,255,255,0) 100%);',
            '    border-radius: 6px 6px 0 0;',
            '}',
            '',
            '@keyframes rainbow-shift {',
            '    0% { background-position: 0% 50%; }',
            '    100% { background-position: 200% 50%; }',
            '}',
            '',
            '@keyframes stripe-move {',
            '    0% { background-position: 0 0; }',
            '    100% { background-position: 40px 0; }',
            '}',
            '',
            '@keyframes pulse-glow {',
            '    0%, 100% { box-shadow: 0 0 6px rgba(255,255,255,0.2), 0 0 12px rgba(255,150,0,0.15); }',
            '    50% { box-shadow: 0 0 10px rgba(255,255,255,0.35), 0 0 20px rgba(255,150,0,0.25); }',
            '}',
            '',
            '@keyframes border-glow {',
            '    0%, 100% { box-shadow: 0 0 8px rgba(255,100,0,0.5); }',
            '    50% { box-shadow: 0 0 15px rgba(255,100,0,0.8), 0 0 25px rgba(255,200,0,0.4); }',
            '}',
            '',
            '#progress-text {',
            '    position: absolute;',
            '    top: 50%;',
            '    left: 50%;',
            '    transform: translate(-50%, -50%);',
            '    font-size: 9px;',
            '    font-weight: bold;',
            '    color: #fff;',
            '    text-shadow: 1px 1px 2px rgba(0,0,0,0.8), 0 0 4px rgba(0,0,0,0.5);',
            '    z-index: 10;',
            '    pointer-events: none;',
            '}',
            '',
            '#loading-spinner {',
            '    width: 40px;',
            '    height: 40px;',
            '    margin: 20px auto 0 auto;',
            '    border: 4px solid #1d292c;',
            '    border-top: 4px solid #f60;',
            '    border-radius: 50%;',
            '    animation: spin 1s linear infinite;',
            '}',
            '',
            '@keyframes spin {',
            '    0% { transform: rotate(0deg); }',
            '    100% { transform: rotate(360deg); }',
            '}',
            '',
            '#evolution-animation {',
            '    display: flex;',
            '    align-items: center;',
            '    justify-content: center;',
            '    margin: 15px auto 0 auto;',
            '    gap: 8px;',
            '    font-size: 32px;',
            '}',
            '',
            '#creature-wrapper {',
            '    position: relative;',
            '    display: inline-block;',
            '}',
            '',
            '#creature {',
            '    position: relative;',
            '    z-index: 5;',
            '    transition: transform 0.15s ease;',
            '    display: inline-block;',
            '    line-height: 1;',
            '}',
            '',
            '#creature.attacking {',
            '    transform: rotate(20deg) scale(1.1);',
            '}',
            '',
            '#creature.evolving {',
            '    transform: scale(1.4);',
            '}',
            '',
            '#enemy {',
            '    transition: transform 0.25s ease, opacity 0.25s ease;',
            '    display: inline-block;',
            '}',
            '',
            '#enemy.eaten {',
            '    transform: translateX(-15px) scale(0) rotate(180deg);',
            '    opacity: 0;',
            '}',
            '',
            '#level-up {',
            '    position: relative;',
            '    margin: 10px auto 0 auto;',
            '    transform: scale(0);',
            '    font-size: 18px;',
            '    font-weight: bold;',
            '    color: #ffd700;',
            '    text-shadow: 0 0 10px #ff8c00, 0 0 20px #ff6600;',
            '    opacity: 0;',
            '    transition: transform 0.2s ease, opacity 0.2s ease;',
            '    pointer-events: none;',
            '    z-index: 100;',
            '    text-align: center;',
            '    height: 24px;',
            '}',
            '',
            '#level-up.show {',
            '    transform: scale(1.2);',
            '    opacity: 1;',
            '}',
            '',
            '',
            '',
            '#xp-bar-container {',
            '    position: relative;',
            '    width: 100px;',
            '    height: 14px;',
            '    margin: 8px auto 0 auto;',
            '    background-color: #1d292c;',
            '    border-radius: 3px;',
            '    overflow: hidden;',
            '}',
            '',
            '#xp-bar {',
            '    height: 100%;',
            '    width: 0%;',
            '    background: linear-gradient(90deg, #4CAF50, #8BC34A);',
            '    transition: width 0.3s ease;',
            '}',
            '',
            '#level-display {',
            '    position: absolute;',
            '    top: 50%;',
            '    left: 50%;',
            '    transform: translate(-50%, -50%);',
            '    font-size: 10px;',
            '    font-weight: bold;',
            '    color: #fff;',
            '    text-shadow: 1px 1px 1px #000;',
            '    z-index: 1;',
            '}',
            '',
            '',
            '#sparkle-container {',
            '    position: absolute;',
            '    top: 50%;',
            '    left: 50%;',
            '    transform: translate(-50%, -50%);',
            '    width: 0;',
            '    height: 0;',
            '    pointer-events: none;',
            '    z-index: 100;',
            '    z-index: 10;',
            '}',
            '',
            '.sparkle {',
            '    position: absolute;',
            '    font-size: 20px;',
            '    opacity: 0;',
            '    transform: translate(-50%, -50%) scale(0);',
            '    transition: none;',
            '}',
            '',
            '.sparkle.active {',
            '    opacity: 1;',
            '    transform: translate(-50%, -50%) scale(1.2) rotate(var(--angle)) translateY(-35px);',
            '    transition: transform 0.4s ease-out, opacity 0.4s ease-out;',
            '}',
            '',
            '',
            '@media (max-width: 480px) {',
            '    #application-splash {',
            '        width: 170px;',
            '    }',
            '}',
            '',
            '@media (max-height: 400px) {',
            '    #application-splash {',
            '        transform: translate(-50%, -50%) scale(0.8);',
            '    }',
            '    #evolution-animation {',
            '        margin-top: 8px;',
            '        font-size: 24px;',
            '    }',
            '}'
        ].join('\n');

        var style = document.createElement('style');
        style.type = 'text/css';
        if (style.styleSheet) {
            style.styleSheet.cssText = css;
        } else {
            style.appendChild(document.createTextNode(css));
        }

        document.head.appendChild(style);
    };

    createCss();
    showSplash();

    // Start fake progress if enabled
    if (USE_FAKE_PROGRESS) {
        startFakeProgress();
    }

    app.on('preload:end', function () {
        app.off('preload:progress');
        if (USE_FAKE_PROGRESS) {
            completeFakeProgress();
        }
    });

    // Only use real progress updates if fake progress is disabled
    if (!USE_FAKE_PROGRESS) {
        app.on('preload:progress', setProgress);
    }

    app.on('hideLoadingScreen', hideSplash);
});
